-- e8eaeafd | ما نواقض الوضوء؟
UPDATE qa_questions SET
  answer = 'من أبرزها: الخارج من السبيلين، معتادًا كان (كالبول والغائط والريح والمني والمذي والودي) أو نادرًا، وهو ناقض بالإجماع؛ والنوم، وهو ناقض في الجملة في قول عامة أهل العلم؛ وزوال العقل بالجنون أو الإغماء أو السُّكْر، ينقض قليله وكثيره بالإجماع. وأما مسّ الفرج فناقض عند الجمهور من غير تقييد بالشهوة، وفي تفصيله خلاف بين الفقهاء؛ وقيد الشهوة إنما هو في لمس المرأة لا في مسّ الفرج.',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج١/ص٢٣٠ و٢٣٤ و٢٤٠ و٢٥٦ (باب ما ينقض الطهارة) | الكلمات المفتاحية: نواقض الوضوء، الطهارة',
  evidence = 'المغني ج١/ص٢٣٠: «أنَّ الخارجَ من السَّبِيلَيْنِ عَلَى ضَرْبَيْنِ: مُعْتادٍ كالبَوْلِ والغائِطِ والمَنِىِّ والمَذْىِ والوَدْىِ والرِّيحِ، فهذا يَنْقُضُ الوُضُوءَ إجْماعًا». وج١/ص٢٣٤: «الضَّرْبُ الثاني النومُ، وهو ناقِضٌ للوُضُوءِ في الجُمْلةِ، في قولِ عَامَّة أهلِ العِلْمِ»، وفيها: «زَوَالُ العَقْلِ علَى ضَرْبَيْن: نَوْمٍ، وغيرِه؛ فأمَّا غيرُ النَّوْمِ، وهو الجُنُونُ والإِغْماءُ والسُّكْرُ وما أشَبَهه من الأدْوِيةِ المُزِيلةِ للعَقْلِ، فيَنْقُضُ الوُضُوءَ يَسِيرُه وكَثِيرهُ إجماعًا». وج١/ص٢٤٠: «الفَرْجُ: اسمٌ لمَخْرَجِ الحَدَثِ، ويتناولُ الذَّكَرَ والدُبُرَ وقُبُلَ المرأةِ، وفى نَقْضِ الوُضُوءِ بجَمِيعِ ذلك خلافٌ في المَذْهَبِ وغيرِه». وقيدُ الشهوة إنما هو في لمس المرأة لا في مسّ الفرج، ج١/ص٢٥٦: «المَشْهُورُ مِنْ مَذْهَبِ أحمدَ، رحمه اللهُ، أنَّ لَمْسَ النِّسَاءِ لِشَهْوةٍ يَنْقُضُ الوُضُوءَ، ولا يَنْقُضُه لِغَيْرِ شَهْوَةٍ».',
  verification_status = 'verified'
