-- 3afc167e | ما حكم الاستنجاء بعد قضاء الحاجة؟
UPDATE qa_questions SET
  answer = 'الاستنجاء (تطهير مخرجي البول والغائط بالماء أو الحجر ونحوه) واجب من الخارج النجس، ولا استنجاء من الريح ولا من النوم. ويجزئ الاقتصار على الحجر بغير خلاف بين أهل العلم، والأفضل أن يستجمر بالحجر ثم يُتبعه الماء.',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج١/ص٢٠٥ و٢٠٨ (باب الاستطابة والحدث) | الكلمات المفتاحية: الاستنجاء',
  evidence = 'المغني ج١/ص٢٠٥: «الاسْتِطابةُ: هي الاسْتِنْجاءُ بالماءِ أو بالأَحْجارِ»، وفيها: «(وليس عَلَى مَنْ نامَ أو خَرَجتْ منه رِيحٌ اسْتِنْجاءٌ) لا نَعْلمُ في هذا خِلافا. قال أبو عبد اللَّه: ليس في الرِّيحِ اسْتِنْجاءٌ». وج١/ص٢٠٨: «وإنْ اقْتَصَرَ عَلَى الحَجَرِ أجْزَأهُ، بغيرِ خلافٍ بين أهلِ العِلْمِ… والأفضلُ أن يَسْتَجْمِرَ بالحَجَر، ثم يُتْبِعَه الماءَ. قال أحمد: إنْ جَمَعَهُما فهو أحَبُّ».',
  verification_status = 'verified'
WHERE id = '3afc167e-d7e3-4615-a174-74777dcb7ff9'
  AND reference = 'كتب الفقه الإسلامي | الكلمات المفتاحية: الاستنجاء'
  AND evidence = 'ثبت عن النبي ﷺ استنجاؤه بالماء والاستجمار بالأحجار في أحاديث السنن.'
  AND answer = 'الاستنجاء (تطهير مخرجي البول والغائط بالماء أو الحجر ونحوه) واجب بعد قضاء الحاجة، ويُستحب الجمع بين الحجر والماء لأثر أكمل في النظافة.';

