-- 8e8fd6e0 | رجل باع سلعة ثم تبيّن أنها معيبة بعد القبض، فما حكم البيع؟
UPDATE qa_questions SET
  answer = 'للمشتري أن يرد السلعة ويفسخ البيع ويسترد الثمن، وهذا محل اتفاق، ويُسمى "خيار العيب". وله كذلك إمساكها مع أخذ أرش العيب عند الحنابلة وإسحاق؛ وقال أبو حنيفة والشافعي: ليس له إلا الإمساك أو الرد بلا أرش، إلا أن يتعذر رد المبيع. والأرش: أن يُقوَّم المبيع صحيحًا ثم معيبًا، فيؤخذ قسط ما بينهما من الثمن.',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج٦/ص٢٢٩ (الفصل الخامس من مسائل الرد بالعيب) | الكلمات المفتاحية: خيار العيب، ألغاز فقهية',
  evidence = 'المغني ج٦/ص٢٢٩: «أنّه إذا اختارَ المُشْترِى إمساكَ المَعيِبِ، وأخْذَ الأرْشِ، فله ذلك. وهذا قولُ إسحاقَ. وقال أبو حنيفةَ، والشّافِعِىُّ: ليس له إلَّا الإمساكُ، أو الرَّدُّ، وليس له أرْشٌ، إلَّا أنْ يَتَعَذَّرَ رَدُّ المَبِيعِ». وفيها بيان الأرش: «أنْ يُقَوَّمَ المبِيعُ صَحِيحًا، ثم يُقَوَّمَ مَعِيبًا، فيُؤْخَذَ قِسْطُ ما بينَهما مِن الثَّمَنِ».',
  verification_status = 'verified'
WHERE id = '8e8fd6e0-990e-4c9a-bff1-4f9242bcba9f'
  AND reference = 'كتب الفقه الإسلامي | الكلمات المفتاحية: خيار العيب، ألغاز فقهية'
  AND evidence = 'مسألة فقهية مجمَع عليها بين الفقهاء تحت باب خيارات البيع.'
